11	|*                                                                            *|
12	\*===----------------------------------------------------------------------===*/
13	
14	#ifndef ORC_RT_C_WRAPPERFUNCTION_H
15	#define ORC_RT_C_WRAPPERFUNCTION_H
16	
17	#include "orc-rt-c/Compiler.h"
18	#include "orc-rt-c/CoreTypes.h"
19	
20	#include <assert.h>
21	#include <stdint.h>
22	#include <stdlib.h>
23	#include <string.h>
24	
25	ORC_RT_C_EXTERN_C_BEGIN
26	
27	typedef union {
28	  char *ValuePtr;
29	  char Value[sizeof(char *)];
30	} orc_rt_WrapperFunctionBufferDataUnion;
31	
32	/**
33	 * orc_rt_WrapperFunctionBuffer is a kind of C-SmallVector with an
34	 * out-of-band error state.
35	 *
36	 * If Size == 0 and Data.ValuePtr is non-zero then the value is in the
37	 * 'out-of-band error' state, and Data.ValuePtr points at a malloc-allocated,
38	 * null-terminated string error message.
39	 *
40	 * If Size <= sizeof(orc_rt_WrapperFunctionBufferData) then the value is in
41	 * the 'small' state and the content is held in the first Size bytes of
42	 * Data.Value.
43	 *
44	 * If Size > sizeof(orc_rt_WrapperFunctionBufferData) then the value is in the
45	 * 'large' state and the content is held in the first Size bytes of the
46	 * memory pointed to by Data.ValuePtr. This memory must have been allocated by
47	 * malloc, and will be freed with free when this value is destroyed.
48	 */
49	typedef struct {
50	  orc_rt_WrapperFunctionBufferDataUnion Data;
51	  size_t Size;
52	} orc_rt_WrapperFunctionBuffer;
53	
54	/**
55	 * Asynchronous return function for an orc-rt wrapper function.
56	 */
57	typedef void (*orc_rt_WrapperFunctionReturn)(
58	    orc_rt_SessionRef S, orc_rt_WrapperFunctionBuffer ResultBytes,
59	    uint64_t CallId);
60	
61	/**
62	 * orc-rt wrapper function prototype.
63	 *
64	 * Session holds a reference to the session object.
65	 * ArgBytes contains the serialized arguments for the wrapper function.
66	 * Return holds a pointer to the return function.
67	 * CallId holds a pointer to the context object for this particular call.
68	 */
69	typedef void (*orc_rt_WrapperFunction)(orc_rt_SessionRef S,
70	                                       orc_rt_WrapperFunctionBuffer ArgBytes,
71	                                       orc_rt_WrapperFunctionReturn Return,
72	                                       uint64_t CallId);
73	
74	/**
75	 * Zero-initialize an orc_rt_WrapperFunctionBuffer.
76	 */
77	static inline void
78	orc_rt_WrapperFunctionBufferInit(orc_rt_WrapperFunctionBuffer *B) {
79	  B->Size = 0;
80	  B->Data.ValuePtr = 0;
81	}
82	
83	/**
84	 * Create an orc_rt_WrapperFunctionBuffer with an uninitialized buffer of
85	 * size Size. The buffer is returned via the DataPtr argument.
86	 */
87	static inline orc_rt_WrapperFunctionBuffer
88	orc_rt_WrapperFunctionBufferAllocate(size_t Size) {
89	  orc_rt_WrapperFunctionBuffer B;
90	  B.Size = Size;
91	  // If Size is 0 ValuePtr must be 0 or it is considered an out-of-band error.
92	  B.Data.ValuePtr = 0;
93	  if (Size > sizeof(B.Data.Value))
94	    B.Data.ValuePtr = (char *)malloc(Size);
95	  return B;
96	}
97	
98	/**
99	 * Create an orc_rt_WrapperFunctionBuffer from the given data range.
100	 */
101	static inline orc_rt_WrapperFunctionBuffer
102	orc_rt_CreateWrapperFunctionBufferFromRange(const char *Data, size_t Size) {
103	  orc_rt_WrapperFunctionBuffer B;
104	  B.Size = Size;
105	  // If Size is 0 ValuePtr must be 0 or it is considered an out-of-band error.
106	  B.Data.ValuePtr = 0;
107	  if (B.Size > sizeof(B.Data.Value)) {
108	    char *Tmp = (char *)malloc(Size);
109	    memcpy(Tmp, Data, Size);
110	    B.Data.ValuePtr = Tmp;
111	  } else if (Size != 0)
112	    memcpy(B.Data.Value, Data, Size);
113	  return B;
114	}
115	
116	/**
117	 * Create an orc_rt_WrapperFunctionBuffer by copying the given string,
118	 * including the null-terminator.
119	 *
120	 * This function copies the input string. The client is responsible for freeing
121	 * the ErrMsg arg.
122	 */
123	static inline orc_rt_WrapperFunctionBuffer
124	orc_rt_CreateWrapperFunctionBufferFromString(const char *Source) {
125	  return orc_rt_CreateWrapperFunctionBufferFromRange(Source,
126	                                                     strlen(Source) + 1);
127	}
128	
129	/**
130	 * Create an orc_rt_WrapperFunctionBuffer representing an out-of-band
131	 * error.
132	 *
133	 * This function copies the input string. The client is responsible for freeing
134	 * the ErrMsg arg.
135	 */
136	static inline orc_rt_WrapperFunctionBuffer
137	orc_rt_CreateWrapperFunctionBufferFromOutOfBandError(const char *ErrMsg) {
138	  orc_rt_WrapperFunctionBuffer B;
139	  B.Size = 0;
140	  char *Tmp = (char *)malloc(strlen(ErrMsg) + 1);
141	  strcpy(Tmp, ErrMsg);
142	  B.Data.ValuePtr = Tmp;
143	  return B;
144	}
145	
146	/**
147	 * This should be called to destroy orc_rt_WrapperFunctionBuffer values
148	 * regardless of their state.
149	 */
150	static inline void
151	orc_rt_WrapperFunctionBufferDispose(orc_rt_WrapperFunctionBuffer *B) {
152	  if (B->Size > sizeof(B->Data.Value) || (B->Size == 0 && B->Data.ValuePtr))
153	    free(B->Data.ValuePtr);
154	}
155	
156	/**
157	 * Get a pointer to the data contained in the given
158	 * orc_rt_WrapperFunctionBuffer.
159	 */
160	static inline char *
161	orc_rt_WrapperFunctionBufferData(orc_rt_WrapperFunctionBuffer *B) {
162	  assert((B->Size != 0 || B->Data.ValuePtr == NULL) &&
163	         "Cannot get data for out-of-band error value");
164	  return B->Size > sizeof(B->Data.Value) ? B->Data.ValuePtr : B->Data.Value;
165	}
166	
167	static inline const char *
168	orc_rt_WrapperFunctionBufferConstData(const orc_rt_WrapperFunctionBuffer *B) {
169	  assert((B->Size != 0 || B->Data.ValuePtr == NULL) &&
170	         "Cannot get data for out-of-band error value");
171	  return B->Size > sizeof(B->Data.Value) ? B->Data.ValuePtr : B->Data.Value;
172	}
173	
174	/**
175	 * Safely get the size of the given orc_rt_WrapperFunctionBuffer.
176	 *
177	 * Asserts that we're not trying to access the size of an error value.
178	 */
179	static inline size_t
180	orc_rt_WrapperFunctionBufferSize(const orc_rt_WrapperFunctionBuffer *B) {
181	  assert((B->Size != 0 || B->Data.ValuePtr == NULL) &&
182	         "Cannot get size for out-of-band error value");
183	  return B->Size;
184	}
185	
186	/**
187	 * Returns 1 if this value is equivalent to a value just initialized by
188	 * orc_rt_WrapperFunctionBufferInit, 0 otherwise.
189	 */
190	static inline size_t
191	orc_rt_WrapperFunctionBufferEmpty(const orc_rt_WrapperFunctionBuffer *B) {
192	  return B->Size == 0 && B->Data.ValuePtr == 0;
193	}
194	
195	/**
196	 * Returns a pointer to the out-of-band error string for this
197	 * orc_rt_WrapperFunctionBuffer, or null if there is no error.
198	 *
199	 * The orc_rt_WrapperFunctionBuffer retains ownership of the error
200	 * string, so it should be copied if the caller wishes to preserve it.
201	 */
202	static inline const char *orc_rt_WrapperFunctionBufferGetOutOfBandError(
203	    const orc_rt_WrapperFunctionBuffer *B) {
204	  return B->Size == 0 ? B->Data.ValuePtr : 0;
205	}
206	
207	ORC_RT_C_EXTERN_C_END
208	
209	#endif /* ORC_RT_C_WRAPPERFUNCTION_H */
