28	/// Provides direct access from/to an ExecutorProcessControl object in the same
29	/// process.
30	class InProcessControllerAccess : public Session::ControllerAccess {
31	public:
32	  /// Pseudo-connection C struct. Used to facilitate calls between InProcessEPC
33	  /// and InProcessControllerAccess without relying on anything but C ABI.
34	  /// Must be kept in-sync with the corresponding struct in InProcessEPC.
35	  struct Connection {
36	    void (*Retain)(Connection *C) = nullptr;
37	    void (*Release)(Connection *C) = nullptr;
38	    void (*Disconnect)(Connection *C) = nullptr;
39	    int (*EnterMessageScope)(Connection *C) = nullptr;
40	    void (*LeaveMessageScope)(Connection *C) = nullptr;
41	
42	    /// Accessors to be set by the InProcessEPC instance.
43	    void *IPEPC = nullptr;
44	    void (*CallJITDispatch)(void *IPEPC, uint64_t CallId,
45	                            orc_rt_ControllerHandlerTag T,
46	                            orc_rt_WrapperFunctionBuffer ArgBytes) = nullptr;
47	    void (*ReturnWrapperResult)(void *IPEPC, uint64_t CallId,
48	                                orc_rt_WrapperFunctionBuffer ResultBytes) =
49	        nullptr;
50	
51	    /// Accessors to be set by the InProcessControllerAccess instance.
52	    void *IPCA = nullptr;
53	    void (*CallWrapper)(void *IPCA, uint64_t CallId, void *Fn,
54	                        orc_rt_WrapperFunctionBuffer ArgBytes) = nullptr;
55	    void (*ReturnJITDispatchResult)(void *IPCA, uint64_t CallId,
56	                                    orc_rt_WrapperFunctionBuffer ResultBytes) =
57	        nullptr;
58	  };
59	
60	  struct ConnectionImpl;
61	
62	  /// Provides access to bootstrap info.
63	  /// Must be kept in-sync with the corresponding struct in InProcessEPC.
64	  struct BootstrapInfoAccess {
65	    uint64_t (*GetPageSize)(void *BIA) = nullptr;
66	    const char *(*GetTargetTriple)(void *BIA) = nullptr;
67	
68	    int (*GetNextValue)(void *BIA, const char **Name, const char **ValueBytes,
69	                        uint64_t *ValueSize) = nullptr;
70	    int (*GetNextSymbol)(void *BIA, const char **Name,
71	                         uint64_t *Addr) = nullptr;
72	  };
73	
74	  struct BootstrapInfoAccessImpl;
75	
76	  /// OnConnect callback type.
77	  ///
78	  /// An instance of this type will be stored in the InProcessControllerAccess
79	  /// object and called from InProcessControllerAccess::connect. The IPCA&
80	  /// reference argument remains valid for the lifetime of the calling IPCA
81	  /// instance. The Connection *C argument is ref-counted; the IPCA holds the
82	  /// initial reference, keeping C alive for at least the duration of the call.
83	  /// Implementations that need to use C after OnConnect returns must call
84	  /// C->Retain(C) (paired with C->Release(C) when finished) to take their own
85	  /// reference. The BI and BCA arguments are valid only for the duration of
86	  /// the call and must not be captured by the callback.
87	  ///
88	  /// It is expected that clients will use these arguments to construct an
89	  /// llvm::orc::InProcessEPC object via that class's Create method, in which
90	  /// case llvm::orc::InProcessEPC::Create will manage the retain and release of
91	  /// Connection *C.
92	  using OnConnectFn = move_only_function<Error(InProcessControllerAccess &IPCA,
93	                                               BootstrapInfo &BI, Connection *C,
94	                                               BootstrapInfoAccess *BCA)>;
95	
96	  /// Create an InProcessControllerAccess instance.
97	  InProcessControllerAccess(Session &S, OnConnectFn OnConnect)
98	      : Session::ControllerAccess(S), OnConnect(std::move(OnConnect)) {}
99	
100	  InProcessControllerAccess(const InProcessControllerAccess &) = delete;
101	  InProcessControllerAccess &
102	  operator=(const InProcessControllerAccess &) = delete;
103	  InProcessControllerAccess(InProcessControllerAccess &&) = delete;
104	  InProcessControllerAccess &operator=(InProcessControllerAccess &&) = delete;
105	
106	  ~InProcessControllerAccess();
107	
108	  void connect(BootstrapInfo BI) override;
109	
110	  void disconnect() override;
111	
112	  void callController(OnControllerCallReturn OnComplete,
113	                      orc_rt_ControllerHandlerTag T,
114	                      WrapperFunctionBuffer ArgBytes) override;
115	  void sendWrapperResult(WrapperFunctionBuffer ResultBytes,
116	                         uint64_t CallId) override;
117	
118	private:
119	  uint64_t registerPendingHandler(OnControllerCallReturn OnComplete);
120	  void doDisconnect();
121	
122	  void callWrapper(uint64_t CallId, void *Fn,
123	                   orc_rt_WrapperFunctionBuffer ArgBytes);
124	  static void callWrapperEntry(void *IPCA, uint64_t CallId, void *Fn,
125	                               orc_rt_WrapperFunctionBuffer ArgBytes);
126	
127	  void returnJITDispatchResult(uint64_t CallId,
128	                               orc_rt_WrapperFunctionBuffer ResultBytes);
129	  static void
130	  returnJITDispatchResultEntry(void *IPCA, uint64_t CallId,
131	                               orc_rt_WrapperFunctionBuffer ResultBytes);
132	
133	  OnConnectFn OnConnect;
134	  ConnectionImpl *C = nullptr;
135	
136	  std::mutex M;
137	  uint64_t NextPendingCall = 0;
138	
139	  using PendingCallsMap = std::unordered_map<uint64_t, OnControllerCallReturn>;
140	  PendingCallsMap PendingCalls;
141	};
142	
143	} // namespace orc_rt
144	
145	#endif // ORC_RT_INPROCESSCONTROLLERACCESS_H
