23	ExecutorProcessInfo::ExecutorProcessInfo(std::string Triple,
24	                                         size_t PageSize) noexcept
25	    : Triple(std::move(Triple)), PageSize(PageSize) {
26	  assert(!this->Triple.empty() && "triple cannot be empty");
27	  assert(isPowerOf2(this->PageSize) && "page-size is not a power of two");
28	}
29	
30	/// Create an ExecutorProcessInfo, auto-detecting property values.
31	Expected<ExecutorProcessInfo> ExecutorProcessInfo::Detect() noexcept {
32	  auto Triple = detectTargetTriple();
33	  auto PageSize = detectPageSize();
34	  if (!PageSize)
35	    return PageSize.takeError();
36	  return ExecutorProcessInfo(std::move(Triple), std::move(*PageSize));
37	}
38	
39	std::string ExecutorProcessInfo::detectTargetTriple() noexcept {
40	  std::string Triple;
41	
42	// Arch
43	#if defined(__x86_64__) || defined(_M_X64)
44	  Triple += "x86_64";
45	#elif defined(__aarch64__) || defined(_M_ARM64)
46	  Triple += "aarch64";
47	#else
48	#error "Unsupported architecture"
49	#endif
50	
51	  // Vendor
52	#if defined(__APPLE__)
53	  Triple += "-apple";
54	#else
55	  Triple += "-unknown";
56	#endif
57	
58	  // OS
59	#if defined(__APPLE__)
60	  Triple += "-darwin";
61	#elif defined(__linux__)
62	  Triple += "-linux";
63	#else
64	#error "Unsupported OS"
65	#endif
66	
67	  return Triple;
68	}
69	
70	Expected<size_t> ExecutorProcessInfo::detectPageSize() noexcept {
71	  long PageSize = sysconf(_SC_PAGESIZE);
72	  if (PageSize == -1)
73	    return make_error<StringError>(strerror(errno));
74	  if (!isPowerOf2(PageSize))
75	    return make_error<StringError>("reported page size " +
76	                                   std::to_string(PageSize) +
77	                                   " is not a power of two");
78	  return static_cast<size_t>(PageSize);
79	}
