20	struct InProcessControllerAccess::ConnectionImpl : public Connection {
21	public:
22	  ConnectionImpl(InProcessControllerAccess &Instance) {
23	    Retain = &retainEntry;
24	    Release = &releaseEntry;
25	    Disconnect = &disconnectEntry;
26	    EnterMessageScope = &enterMessageScopeEntry;
27	    LeaveMessageScope = &leaveMessageScopeEntry;
28	    IPCA = &Instance;
29	    CallWrapper = InProcessControllerAccess::callWrapperEntry;
30	    ReturnJITDispatchResult =
31	        InProcessControllerAccess::returnJITDispatchResultEntry;
32	  }
33	
34	private:
35	  void retain() {
36	    std::scoped_lock<std::mutex> Lock(M);
37	    ++RefCount;
38	  }
39	
40	  static void retainEntry(Connection *C) {
41	    static_cast<ConnectionImpl *>(C)->retain();
42	  }
43	
44	  int release() {
45	    std::scoped_lock<std::mutex> Lock(M);
46	    --RefCount;
47	    return RefCount == 0;
48	  }
49	
50	  static void releaseEntry(Connection *C) {
51	    if (static_cast<ConnectionImpl *>(C)->release())
52	      delete static_cast<ConnectionImpl *>(C);
53	  }
54	
55	  void disconnect() {
56	    {
57	      std::unique_lock<std::mutex> Lock(M);
58	      if (!Connected)
59	        return;
60	      Connected = false;
61	      CV.wait(Lock, [this]() { return InFlightCalls == 0; });
62	    }
63	    static_cast<InProcessControllerAccess *>(IPCA)->doDisconnect();
64	  }
65	
66	  static void disconnectEntry(Connection *C) {
67	    static_cast<ConnectionImpl *>(C)->disconnect();
68	  }
69	
70	  int enterMessageScope() {
71	    std::scoped_lock<std::mutex> Lock(M);
72	    if (!Connected)
73	      return 0;
74	    ++InFlightCalls;
75	    return 1;
76	  }
77	
78	  static int enterMessageScopeEntry(Connection *C) {
79	    return static_cast<ConnectionImpl *>(C)->enterMessageScope();
80	  }
81	
82	  void leaveMessageScope() {
83	    bool NotifyCV = false;
84	    {
85	      std::scoped_lock<std::mutex> Lock(M);
86	      --InFlightCalls;
87	      if (InFlightCalls == 0 && !Connected)
88	        NotifyCV = true;
89	    }
90	    if (NotifyCV)
91	      CV.notify_one();
92	  }
93	
94	  static void leaveMessageScopeEntry(Connection *C) {
95	    static_cast<ConnectionImpl *>(C)->leaveMessageScope();
96	  }
97	
98	  std::mutex M;
99	  std::condition_variable CV;
100	  bool Connected = true;
101	  size_t InFlightCalls = 0;
102	  size_t RefCount = 1;
103	};
104	
105	struct InProcessControllerAccess::BootstrapInfoAccessImpl
106	    : public BootstrapInfoAccess {
107	public:
108	  BootstrapInfoAccessImpl(BootstrapInfo &BI)
109	      : BI(BI), BVI(BI.values().begin()), BSI(BI.symbols().begin()) {
110	    GetPageSize = getPageSizeEntry;
111	    GetTargetTriple = getTargetTripleEntry;
112	    GetNextValue = getNextValueEntry;
113	    GetNextSymbol = getNextSymbolEntry;
114	  }
115	
116	private:
117	  uint64_t getPageSize() const noexcept { return BI.processInfo().pageSize(); }
118	
119	  static uint64_t getPageSizeEntry(void *BIA) noexcept {
120	    return static_cast<BootstrapInfoAccessImpl *>(BIA)->getPageSize();
121	  }
122	
123	  const char *getTargetTriple() const noexcept {
124	    return BI.processInfo().targetTriple().c_str();
125	  }
126	
127	  static const char *getTargetTripleEntry(void *BIA) {
128	    return static_cast<BootstrapInfoAccessImpl *>(BIA)->getTargetTriple();
129	  }
130	
131	  int getNextValue(const char **Name, const char **Value, uint64_t *ValueSize) {
132	    if (BVI == BI.values().end())
133	      return 0;
134	    *Name = BVI->first.c_str();
135	    *Value = BVI->second.data();
136	    *ValueSize = BVI->second.size();
137	    ++BVI;
138	    return 1;
139	  }
140	
141	  static int getNextValueEntry(void *BIA, const char **Name, const char **Value,
142	                               uint64_t *ValueSize) {
143	    return static_cast<BootstrapInfoAccessImpl *>(BIA)->getNextValue(
144	        Name, Value, ValueSize);
145	  }
146	
147	  int getNextSymbol(const char **Name, uint64_t *Addr) {
148	    if (BSI == BI.symbols().end())
149	      return 0;
150	    *Name = BSI->first.c_str();
151	    *Addr = ExecutorAddr::fromPtr(BSI->second).getValue();
152	    ++BSI;
153	    return 1;
154	  }
155	
156	  static int getNextSymbolEntry(void *BIA, const char **Name, uint64_t *Addr) {
157	    return static_cast<BootstrapInfoAccessImpl *>(BIA)->getNextSymbol(Name,
158	                                                                      Addr);
159	  }
160	
161	  BootstrapInfo &BI;
162	  BootstrapInfo::ValueMap::iterator BVI;
163	  SimpleSymbolTable::iterator BSI;
164	};
