166	InProcessControllerAccess::~InProcessControllerAccess() {
167	  // 'if (C)' to handle the case where the instance is destroyed without
168	  // connect ever being run. (TODO: should calling 'connect' be required?)
169	  if (C)
170	    C->Release(C);
171	}
172	
173	void InProcessControllerAccess::connect(BootstrapInfo BI) {
174	  assert(!C && "connect called twice?");
175	  C = new ConnectionImpl(*this);
176	  BootstrapInfoAccessImpl BIA(BI);
177	
178	  if (auto Err = OnConnect(*this, BI, C, &BIA)) {
179	    reportError(std::move(Err));
180	    // Call disconnect. There's a benign race here: if IPEPC also called
181	    // C->Disconnect(C) then it might have acquired responsibility for calling
182	    // InProcessControllerAccess::onDisconnect. In this case control may return
183	    // from disconnect below early, potentially causing us to return from
184	    // 'connect' before notifyDisconnect is called. This may lead to confusing
185	    // logs (since reportError will log error but connect will appear to
186	    // succeed), however onDisconnect will still be called eventually, and the
187	    // Session will detach as if the remote had initiated the action after a
188	    // successful connect.
189	    disconnect();
190	    return;
191	  }
192	
193	  assert(C->IPEPC && "IPEPC not set by OnConnect");
194	  assert(C->CallJITDispatch && "CallJITDispatch not set by OnConnect");
195	  assert(C->ReturnWrapperResult && "ReturnWrapperResult not set by OnConnect");
196	}
197	
198	void InProcessControllerAccess::disconnect() {
199	  assert(C && "disconnect called before connect");
200	  C->Disconnect(C);
201	}
202	
203	void InProcessControllerAccess::callController(
204	    OnControllerCallReturn OnComplete, orc_rt_ControllerHandlerTag T,
205	    WrapperFunctionBuffer ArgBytes) {
206	  assert(C && "callController called before connect");
207	  if (C->EnterMessageScope(C)) {
208	    C->CallJITDispatch(C->IPEPC, registerPendingHandler(std::move(OnComplete)),
209	                       T, ArgBytes.release());
210	    C->LeaveMessageScope(C);
211	  } else
212	    // Synchronous failure: the connection is already gone, so the call can't be
213	    // sent. The caller is still on the stack, so fail the handler inline.
214	    failControllerCallInline(std::move(OnComplete));
215	}
216	
217	void InProcessControllerAccess::sendWrapperResult(
218	    WrapperFunctionBuffer ResultBytes, uint64_t CallId) {
219	  assert(C && "sendWrapperResult called before connect");
220	  if (C->EnterMessageScope(C)) {
221	    C->ReturnWrapperResult(C->IPEPC, CallId, ResultBytes.release());
222	    C->LeaveMessageScope(C);
223	  }
224	}
