226	uint64_t InProcessControllerAccess::registerPendingHandler(
227	    OnControllerCallReturn OnComplete) {
228	  std::scoped_lock<std::mutex> Lock(M);
229	  PendingCalls[NextPendingCall] = std::move(OnComplete);
230	  return NextPendingCall++;
231	}
232	
233	void InProcessControllerAccess::doDisconnect() {
234	  // Drain pending calls.
235	  PendingCallsMap ToDrain;
236	  {
237	    std::scoped_lock<std::mutex> Lock(M);
238	    ToDrain = std::move(PendingCalls);
239	  }
240	  for (auto &[_, H] : ToDrain)
241	    failPendingControllerCall(std::move(H));
242	
243	  notifyDisconnected();
244	}
