260	void InProcessControllerAccess::returnJITDispatchResult(
261	    uint64_t CallId, orc_rt_WrapperFunctionBuffer ResultBytes) {
262	
263	  OnControllerCallReturn OnComplete;
264	  {
265	    std::scoped_lock<std::mutex> Lock(M);
266	    auto I = PendingCalls.find(CallId);
267	    if (I != PendingCalls.end()) {
268	      OnComplete = std::move(I->second);
269	      PendingCalls.erase(I);
270	    }
271	  }
272	
273	  if (!OnComplete)
274	    return reportError(make_error<StringError>("Invalid call id"));
275	
276	  handleControllerCallResult(std::move(OnComplete),
277	                             WrapperFunctionBuffer(ResultBytes));
278	}
